import { useState } from 'react';

export default function App() {
  const [d, setD] = useState([{ id: 1, nama: 'Kopi' }, { id: 2, nama: 'Teh' }]);
  return (
    <div>
      <button onClick={() => setD(d.filter((x) => x.id !== 1))}>Hapus Kopi</button>
      <ul>{d.map((x) => <li key={x.id}>{x.nama}</li>)}</ul>
    </div>
  );
}

